from lib import *
S = SS('p20')
steps = [
    step("进程池的固定成本。本机 10 个核心,Python 3.14 在 macOS 上的默认启动方式是 spawn。创建 4 进程的池并跑完第一个空任务(冷启动)要 83 ms;池预热之后,一个空任务来回一趟的中位数是 0.141 ms(p95 0.193 ms)。所以池要建一次、反复用,不能每个页面新建。", t=tl(S(1)), done=lidx(S(1), '预热之后'), mark=lidx(S(1), '冷启动'), b=bars([['冷启动 ms', 83, '83'], ['预热后一个空任务来回 ms', 0.141, '0.141']], 90, mark=[0], done=[1]), kv=KV([['冷启动', '83 ms'], ['预热后来回一趟', '0.141 ms'], ['启动方式', 'spawn']], ['冷启动'])),
    step("同样数量的页面,直接解析 / 8 个线程 / 4 个进程 / 8 个进程(map 用 chunksize=n//32,池已预热,3 次中位数)。6KB×4000:468 / 485 / 123 / 77 ms;125KB×300:655 / 559 / 183 / 112;2570KB×20:915 / 763 / 253 / 173。8 个进程比直接解析快 5.3 到 6.2 倍,在 6 KB 到 2.5 MB 之间几乎不随页面大小变化;8 个线程只快 0 到 1.2 倍,甚至在 6 KB 时更慢(485 对 468 ms)——lxml 解析基本不能靠线程加速。", t=tl(S(2)), done=lidx(S(2), '6KB', '125KB', '2570KB'), mark=lidx(S(2), '635KB', '25KB'), b=bars([['6KB:直接 ms', 468, '468'], ['6KB:线程×8 ms', 485, '485'], ['6KB:进程×8 ms', 77, '77'], ['2570KB:直接 ms', 915, '915'], ['2570KB:进程×8 ms', 173, '173']], 920, mark=[1], done=[2, 4]), kv=KV([['8 个进程', '快 5.3–6.2 倍'], ['8 个线程', '基本不加速'], ['页面大小', '6 KB 到 2.5 MB 都划算']], ['8 个进程'])),
    step("只传输页面的成本(子进程什么也不解析,只返回长度):5 KB 来回一趟 0.137 ms,100 KB 是 0.154 ms,2000 KB 是 0.652 ms,20000 KB 是 9.482 ms,其中 pickle.dumps 本身分别是 0.001、0.003、0.044、2.532 ms。传输成本随字节数线性增长:2 MB 的页面要 0.65 ms,而解析它(2570 KB 单页 47.64 ms)要贵得多,所以传输不是瓶颈。", t=tl(S(3)), done=lidx(S(3), '20000 KB', '2000 KB'), mark=lidx(S(3), '5 KB', '100 KB'), b=bars([['5 KB 来回 ms', 0.137, '0.137'], ['2000 KB 来回 ms', 0.652, '0.652'], ['20000 KB 来回 ms', 9.482, '9.482']], 10, done=[2]), kv=KV([['2000 KB', '来回 0.652 ms'], ['单页解析 2570 KB', '47.64 ms'], ['结论', '传输 ≪ 解析']], ['结论'])),
    step("返回值的坑:让子进程返回解析好的 lxml 树会报错 TypeError: cannot pickle 'HtmlElement' object——返回值必须能 pickle,只能返回提取出来的数据。返回一个整数(1077 个链接数)3.03 ms;返回全部 1077 个链接字符串的列表 4.32 ms(序列化后约 19 KB)。", t=tl(S(4)), done=lidx(S(4), '返回一个整数'), mark=lidx(S(4), 'cannot pickle'), kv=KV([['返回 lxml 树', 'TypeError: cannot pickle'], ['返回整数', '3.03 ms'], ['返回 1077 个链接', '4.32 ms,约 19 KB']], ['返回 lxml 树'])),
    step("批量提交的影响:4000 个约 6 KB 的小页面(单页解析 0.15 ms),8 个进程。直接解析 479 ms;map 的 chunksize=1 是 371 ms,只比直接解析快 1.29 倍——每个小任务都要付一次 0.14 ms 左右的来回;chunksize=8 是 78 ms(6.15 倍),chunksize=125 是 76 ms(6.28 倍)。任务小的时候,不批量就浪费掉大部分收益。", t=tl(S(5)), done=lidx(S(5), 'chunksize=8', 'chunksize=125'), mark=lidx(S(5), 'chunksize=1 '), b=bars([['直接解析 ms', 479, '479'], ['chunksize=1 ms', 371, '371'], ['chunksize=8 ms', 78, '78'], ['chunksize=125 ms', 76, '76']], 480, mark=[1], done=[2, 3]), kv=KV([['chunksize=1', '1.29 倍'], ['chunksize=8', '6.15 倍'], ['chunksize=125', '6.28 倍']], ['chunksize=1'])),
]
A = mkartp('p20', 20, '爬虫,进程池,ProcessPoolExecutor,lxml,解析,chunksize,GIL,Python,真实验证,动画演示',
    '实测把 HTML 解析放进进程池:池冷启动 83 ms、预热后一个任务来回 0.141 ms;6 KB 到 2.5 MB 的页面 8 个进程都比直接解析快 5.3–6.2 倍,8 个线程基本不加速;传输页面的成本远小于解析;lxml 树不能返回;map 的 chunksize=1 只快 1.29 倍,批量后 6.15 倍。',
    '上一篇发现线程池帮不了 CPU 密集的解析。进程池能帮多少、什么时候值得、要付出什么代价?这篇在本机 10 个核心上量:启动成本、不同页面大小下的加速比、传输页面的开销、返回值的限制,以及批量提交的影响。',
    [('5.3–6.2 倍', '8 个进程相对直接解析的加速比(页面 6 KB 到 2.5 MB)'), ('0.141 ms', '预热后的进程池,一个空任务来回一趟的中位数'), ('1.29 对 6.15 倍', '小页面用 chunksize=1 与 chunksize=8 的加速比')],
    [('固定成本', '<p>进程池冷启动(4 个进程)约 83 ms,预热之后每个任务来回要 0.141 ms。池要全局建一次反复用。</p>'),
     ('什么时候值得', '<p>在我的页面(一个表格页,解析结果只是数一数链接)上,8 个进程在 6 KB 到 2.5 MB 都快 5.3–6.2 倍,线程池基本不加速(0–1.2 倍)。这个收益依赖于每个任务都足够重、并且我批量提交了;核心数只有 10,所以 8 个进程接近用满。</p>'),
     ('传输页面贵不贵', '<p>把页面传给子进程要序列化:2 MB 来回约 0.65 ms,20 MB 约 9.5 ms,相对解析的耗时(2.5 MB 页面 47.64 ms)是小头。</p>'),
     ('返回什么', '<p>子进程的返回值必须能 pickle,lxml 的元素树不行(<code>TypeError: cannot pickle &#39;HtmlElement&#39; object</code>)。应该在子进程里就提取出需要的数据,只返回字符串、数字、列表之类。</p>'),
     ('批量提交', '<p>对 6 KB 这种小页面,解析一个只要 0.15 ms,和来回一趟的 0.14 ms 差不多。<code>map(..., chunksize=1)</code> 只快 1.29 倍,<code>chunksize=8</code> 以上才到 6 倍。任务越小,越要批量。</p>')],
    steps,
    [ENV_P + '。页面是同一种表格结构按目标大小生成(实际 6 KB、25 KB、125 KB、635 KB、2570 KB);解析函数是 lxml.html.fromstring 加 xpath 数链接;进程池和线程池都预热后计时,3 次取中位数;进程池 map 的 chunksize 取 n//32;进程启动方式为 macOS 默认的 spawn;实验脚本用 __main__ 保护',
     '没有验证:Linux 上 fork 启动方式的成本;核心数更少的机器上的加速比;解析结果更大(需要返回整棵数据)时的传输成本;共享内存、mmap 等免拷贝传递页面的办法;进程池与 asyncio 结合时 run_in_executor 的额外开销(上一篇用过,没拆开测);不同解析库(如 selectolax)的表现;内存占用(每个进程各自加载 lxml)'],
    '进程池解析')
